namespace {
mainframes::Passage passage;
constexpr char routeLoader[] = R"tooljs(// SPDX-License-Identifier: GPL-3.0-only
// Generated by Tool WebAssembly. Compile once on demand. Instantiate fresh state for each preview.
const actions = Object.freeze({ enter: 1, input: 2, passThrough: 3, output: 4, exit: 5, close: 6 });
let compiled;

async function compileRoute() {
    const url = new URL("./tool-route.wasm", import.meta.url);
    const response = await fetch(url);
    if (!response.ok) throw new Error(`Could not load Tool route module (${response.status})`);
    return WebAssembly.compileStreaming(response);
}

export async function openRoute(handle, payloadBytes) {
    if (!Number.isInteger(handle) || handle < 1 || handle > 0xffffffff) {
        throw new RangeError("Expected a nonzero 32-bit preview handle");
    }
    if (!Number.isInteger(payloadBytes) || payloadBytes < 0 || payloadBytes > 4096) {
        throw new RangeError("Expected 0 to 4096 payload bytes");
    }
    compiled ??= compileRoute().catch(error => {
        compiled = undefined;
        throw error;
    });
    const instance = await WebAssembly.instantiate(await compiled);
    const { tool_route_abi, tool_route_state, tool_route_step } = instance.exports;
    if (tool_route_abi() !== 1) throw new Error("Unsupported Tool route ABI");

    const step = (action, operation = 0, bytes = 0) => {
        if (tool_route_step(actions[action], handle, operation, bytes) !== 1) {
            throw new Error(`Tool route rejected ${action}`);
        }
    };
    step("enter");
    step("input", 1, payloadBytes);
    return Object.freeze({
        passThrough: () => step("passThrough"),
        output: () => step("output"),
        exit: () => step("exit"),
        close: () => step("close"),
        state: tool_route_state
    });
}
)tooljs";
}

extern "C" unsigned tool_route_abi() { return mainframes::abiVersion; }
extern "C" unsigned tool_route_state() { return static_cast<unsigned>(passage.state()); }
extern "C" unsigned tool_javascript_size() { return sizeof(routeLoader) - 1; }
extern "C" unsigned tool_javascript_byte(unsigned index) {
    return index < tool_javascript_size() ? static_cast<unsigned char>(routeLoader[index]) : 256;
}
extern "C" unsigned tool_route_step(unsigned action, unsigned handle, unsigned operation, unsigned bytes) {
    return static_cast<unsigned>(passage.step(static_cast<mainframes::Action>(action), handle,
                                              static_cast<mainframes::Operation>(operation), bytes));
}

